import{_ as a,o,c as i,a2 as l}from"./chunks/framework.DpXDHk3d.js";const d=JSON.parse('{"title":"13.2 停电、验电、装设接地线","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-2-ting-dian-yan-dian-zhuang-she-jie-di-xian.md","filePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-2-ting-dian-yan-dian-zhuang-she-jie-di-xian.md","lastUpdated":1793096070000}'),n={name:"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-2-ting-dian-yan-dian-zhuang-she-jie-di-xian.md"};function e(s,t,r,u,g,c){return o(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="_13-2-停电、验电、装设接地线" tabindex="-1">13.2 停电、验电、装设接地线 <a class="header-anchor" href="#_13-2-停电、验电、装设接地线" aria-label="Permalink to &quot;13.2 停电、验电、装设接地线&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>这一节把&quot;技术措施&quot;落到实处:怎么停电、怎么验电、接地线怎么装(先后顺序不能错),以及标示牌和遮栏的作用。顺序问题是判断题最爱挖的坑。</p><h2 id="一、停电" tabindex="-1">一、停电 <a class="header-anchor" href="#一、停电" aria-label="Permalink to &quot;一、停电&quot;">​</a></h2><p>停电不只是&quot;断开开关&quot;,要求做到:</p><ul><li><strong>断开检修设备的电源</strong>,拉开隔离开关或断路器,形成<strong>明显的断开点</strong>;</li><li>断开开关后,相关<strong>熔断器、操作电源</strong>也要断开;</li><li>有反送电可能的地点(如双电源、自备电源)也要可靠隔离。</li></ul><blockquote><p>⚠️ 判断题常考:停电必须形成<strong>明显的断开点</strong>,防止&quot;假停电&quot;或误送电。</p></blockquote><h2 id="二、验电-确认没电" tabindex="-1">二、验电(确认没电) <a class="header-anchor" href="#二、验电-确认没电" aria-label="Permalink to &quot;二、验电(确认没电)&quot;">​</a></h2><ol><li>先检查<strong>验电器(试电笔/验电笔)本身是否完好</strong>——在<strong>有电设备</strong>上试一下,确认验电器能亮;</li><li>再对检修设备各相导线<strong>逐相验电</strong>;</li><li>验电时手不要直接碰触导线,验电后仍要按&quot;没电&quot;对待(装接地线)。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>验电器先在有电设备上验证 ──► 再对检修设备逐相验电 ──► 确认无电</span></span></code></pre></div><blockquote><p>⚠️ 判断题高频:<strong>验电器必须先在有电设备上验证完好</strong>,再验检修设备;验电要&quot;逐相&quot;进行。</p></blockquote><h2 id="三、装设接地线-最关键的保命措施" tabindex="-1">三、装设接地线(最关键的保命措施) <a class="header-anchor" href="#三、装设接地线-最关键的保命措施" aria-label="Permalink to &quot;三、装设接地线(最关键的保命措施)&quot;">​</a></h2><ul><li>检修设备停电、验电确认无电后,<strong>立即装设接地线</strong>;</li><li>接地线用<strong>专用接地线(三相短路接地线)</strong>,截面足够、连接可靠;</li><li><strong>装设顺序(必背)</strong>: <ol><li><strong>先接接地端</strong>(与接地网/接地体连接);</li><li><strong>再接导体端</strong>(挂在检修设备的导线上);</li></ol></li><li><strong>拆除顺序相反</strong>:先拆导体端,后拆接地端;</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>装设: 接地端 ──► 导体端</span></span>
<span class="line"><span>拆除: 导体端 ──► 接地端  (顺序相反)</span></span></code></pre></div><blockquote><p>⚠️ 为什么顺序不能错?<strong>先接接地端</strong>,保证接地线始终&quot;一头可靠接地&quot;,即使另一端碰上带电导体,也只会对地短路跳闸,不会电到人。</p></blockquote><h2 id="四、悬挂标示牌、装设遮栏" tabindex="-1">四、悬挂标示牌、装设遮栏 <a class="header-anchor" href="#四、悬挂标示牌、装设遮栏" aria-label="Permalink to &quot;四、悬挂标示牌、装设遮栏&quot;">​</a></h2><ul><li>在检修工作地点、可能送电的开关上,悬挂<strong>标示牌</strong>,如: <ul><li>&quot;<strong>禁止合闸,有人工作!</strong>&quot;——挂在断开的开关、刀闸操作机构上;</li><li>&quot;<strong>止步,高压危险!</strong>&quot;——挂在遮栏、邻近带电体处;</li></ul></li><li><strong>装设遮栏</strong>:围住工作区,防止误入带电区域、防止误送电;</li><li>工作结束、人员撤离后,才能拆除标示牌和遮栏。</li></ul><blockquote><p>💡 通俗理解:<strong>标示牌是&quot;给开关看的警告&quot;,遮栏是&quot;给人围的护栏&quot;</strong>——一个防误合闸,一个防误进入。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 停电要形成<strong>明显断开点</strong>。</li><li>✅ 验电器<strong>先在有电设备验证</strong>、再逐相验电。</li><li>✅ 接地线<strong>先接接地端,后接导体端</strong>;拆除顺序相反。</li><li>✅ 标示牌:开关上挂&quot;禁止合闸,有人工作&quot;;遮栏防止误入。</li><li>⚠️ 易混点:装接地线&quot;先接地端后导体端&quot;,拆除&quot;先导体端后接地端&quot;——顺序方向一定要分清。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>停电要有明显断开点,验电要先验证验电器、再逐相验。</li><li>接地线装设&quot;先接地端、后导体端&quot;,拆除相反。</li><li>标示牌和遮栏一起,才把检修区域&quot;锁&quot;安全。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)停电检修时,应形成明显的断开点。( )</li><li>(单选)验电器使用前,应当()。 A. 直接在检修设备上试　B. 先在带电设备上验证是否完好　C. 先接地　D. 不需要检查</li><li>(判断)装设接地线的顺序是:先接导体端,后接接地端。( )</li><li>(单选)拆除接地线的顺序是()。 A. 先拆接地端,后拆导体端　B. 先拆导体端,后拆接地端　C. 随便拆　D. 先拆中间</li><li>(判断)检修工作结束前,可在断开的开关上挂&quot;禁止合闸,有人工作&quot;标示牌。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。要有明显断开点。</li><li><strong>B</strong>。先在有电设备上验证验电器完好。</li><li><strong>×</strong>。应先接接地端,后接导体端。</li><li><strong>B</strong>。拆除顺序与装设相反:先拆导体端,后拆接地端。</li><li><strong>√</strong>。标示牌防误合闸,是检修的保障。</li></ol></details>`,25)])])}const q=a(n,[["render",e]]);export{d as __pageData,q as default};
